  1→//! Configuration validation rules.
  2→//!
  3→//! This module validates configuration for correctness:
  4→//! - Steps must have either template or command
  5→//! - depends_on must reference existing steps
  6→//! - Workflows must reference existing steps
  7→//! - No circular dependencies allowed
  8→
  9→use crate::config::schema::BivvyConfig;
 10→use crate::error::{BivvyError, Result};
 11→use std::collections::HashSet;
 12→
 13→/// Validation error with context.
 14→#[derive(Debug, Clone)]
 15→pub struct ValidationError {
 16→    /// Rule identifier
 17→    pub rule: String,
 18→    /// Human-readable error message
 19→    pub message: String,
 20→    /// Step name if error is step-specific
 21→    pub step: Option<String>,
 22→    /// Workflow name if error is workflow-specific
 23→    pub workflow: Option<String>,
 24→}
 25→
 26→/// Validate a configuration and return all errors.
 27→///
 28→/// This function collects all validation errors rather than stopping
 29→/// at the first one, allowing users to fix multiple issues at once.
 30→pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
 31→    let mut errors = Vec::new();
 32→
 33→    errors.extend(validate_steps(config));
 34→    errors.extend(validate_workflows(config));
 35→    errors.extend(validate_dependencies(config));
 36→
 37→    errors
 38→}
 39→
 40→/// Validate step definitions.
 41→fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
 42→    let mut errors = Vec::new();
 43→
 44→    for (name, step) in &config.steps {
 45→        // Step must have either template or command
 46→        if step.template.is_none() && step.command.is_none() {
 47→            errors.push(ValidationError {
 48→                rule: "missing-command".to_string(),
 49→                message: format!("Step '{}' must have either 'template' or 'command'", name),
 50→                step: Some(name.clone()),
 51→                workflow: None,
 52→            });
 53→        }
 54→
 55→        // Validate depends_on references
 56→        for dep in &step.depends_on {
 57→            if !config.steps.contains_key(dep) {
 58→                errors.push(ValidationError {
 59→                    rule: "unknown-step".to_string(),
 60→                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
 61→                    step: Some(name.clone()),
 62→                    workflow: None,
 63→                });
 64→            }
 65→        }
 66→    }
 67→
 68→    errors
 69→}
 70→
 71→/// Validate workflow definitions.
 72→fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
 73→    let mut errors = Vec::new();
 74→
 75→    for (name, workflow) in &config.workflows {
 76→        // Validate step references
 77→        for step_name in &workflow.steps {
 78→            if !config.steps.contains_key(step_name) {
 79→                errors.push(ValidationError {
 80→                    rule: "unknown-workflow-step".to_string(),
 81→                    message: format!(
 82→                        "Workflow '{}' references step '{}' which does not exist",
 83→                        name, step_name
 84→                    ),
 85→                    step: None,
 86→                    workflow: Some(name.clone()),
 87→                });
 88→            }
 89→        }
 90→
 91→        // Validate override references
 92→        for step_name in workflow.overrides.keys() {
 93→            if !workflow.steps.contains(step_name) {
 94→                errors.push(ValidationError {
 95→                    rule: "unknown-override-step".to_string(),
 96→                    message: format!(
 97→                        "Workflow '{}' has override for '{}' which is not in the workflow",
 98→                        name, step_name
 99→                    ),
100→                    step: None,
101→                    workflow: Some(name.clone()),
102→                });
103→            }
104→        }
105→    }
106→
107→    errors
108→}
109→
110→/// Validate step dependencies for cycles.
111→fn validate_dependencies(config: &BivvyConfig) -> Vec<ValidationError> {
112→    let mut errors = Vec::new();
113→    let mut visited = HashSet::new();
114→    let mut rec_stack = HashSet::new();
115→    let mut path = Vec::new();
116→
117→    for step_name in config.steps.keys() {
118→        if let Some(cycle) =
119→            detect_cycle(step_name, config, &mut visited, &mut rec_stack, &mut path)
120→        {
121→            errors.push(ValidationError {
122→                rule: "circular-dependency".to_string(),
123→                message: format!("Circular dependency detected: {}", cycle),
124→                step: Some(step_name.clone()),
125→                workflow: None,
126→            });
127→            break; // Only report one cycle
128→        }
129→    }
130→
131→    errors
132→}
133→
134→fn detect_cycle(
135→    step: &str,
136→    config: &BivvyConfig,
137→    visited: &mut HashSet<String>,
138→    rec_stack: &mut HashSet<String>,
139→    path: &mut Vec<String>,
140→) -> Option<String> {
141→    if rec_stack.contains(step) {
142→        // Found cycle - format it
143→        let cycle_start = path.iter().position(|s| s == step).unwrap();
144→        let cycle: Vec<_> = path[cycle_start..].to_vec();
145→        return Some(format!("{} -> {}", cycle.join(" -> "), step));
146→    }
147→
148→    if visited.contains(step) {
149→        return None;
150→    }

  1→//! Environment variable handling.
  2→//!
  3→//! This module handles loading environment variables from various sources
  4→//! and detecting sensitive values that should be masked in output.
  5→
  6→use crate::error::{BivvyError, Result};
  7→use std::collections::HashMap;
  8→use std::fs;
  9→use std::path::Path;
 10→
 11→/// Built-in secret patterns that are always masked.
 12→///
 13→/// These patterns use simple glob-style matching where `*` matches
 14→/// any characters.
 15→pub const SECRET_PATTERNS: &[&str] = &[
 16→    "*_KEY",
 17→    "*_SECRET",
 18→    "*_TOKEN",
 19→    "*_PASSWORD",
 20→    "*_CREDENTIAL",
 21→    "API_KEY",
 22→    "SECRET_KEY",
 23→    "ACCESS_TOKEN",
 24→    "AUTH_TOKEN",
 25→    "DATABASE_URL",
 26→    "REDIS_URL",
 27→    "AWS_*",
 28→    "GITHUB_TOKEN",
 29→    "OPENAI_API_KEY",
 30→];
 31→
 32→/// Load environment variables from system.
 33→pub fn load_system_env() -> HashMap<String, String> {
 34→    std::env::vars().collect()
 35→}
 36→
 37→/// Load environment variables from a dotenv-style file.
 38→///
 39→/// # Format
 40→///
 41→/// ```text
 42→/// # Comment
 43→/// KEY=value
 44→/// QUOTED="value with spaces"
 45→/// SINGLE='also works'
 46→/// ```
 47→///
 48→/// # Errors
 49→///
 50→/// Returns `ConfigNotFound` if the file doesn't exist.
 51→/// Returns `ConfigParseError` for invalid lines.
 52→pub fn load_env_file(path: &Path) -> Result<HashMap<String, String>> {
 53→    let content = fs::read_to_string(path).map_err(|e| {
 54→        if e.kind() == std::io::ErrorKind::NotFound {
 55→            BivvyError::ConfigNotFound {
 56→                path: path.to_path_buf(),
 57→            }
 58→        } else {
 59→            BivvyError::Io(e)
 60→        }
 61→    })?;
 62→
 63→    parse_dotenv(&content, path)
 64→}
 65→
 66→/// Load env file if it exists, return empty map otherwise.
 67→pub fn load_env_file_optional(path: &Path) -> HashMap<String, String> {
 68→    load_env_file(path).unwrap_or_default()
 69→}
 70→
 71→/// Parse dotenv-style content.
 72→fn parse_dotenv(content: &str, source_path: &Path) -> Result<HashMap<String, String>> {
 73→    let mut env = HashMap::new();
 74→
 75→    for (line_num, line) in content.lines().enumerate() {
 76→        let line = line.trim();
 77→
 78→        // Skip empty lines and comments
 79→        if line.is_empty() || line.starts_with('#') {
 80→            continue;
 81→        }
 82→
 83→        // Parse KEY=value
 84→        if let Some(eq_pos) = line.find('=') {
 85→            let key = line[..eq_pos].trim().to_string();
 86→            let mut value = line[eq_pos + 1..].trim().to_string();
 87→
 88→            // Remove surrounding quotes if present
 89→            if ((value.starts_with('"') && value.ends_with('"'))
 90→                || (value.starts_with('\'') && value.ends_with('\'')))
 91→                && value.len() >= 2
 92→            {
 93→                value = value[1..value.len() - 1].to_string();
 94→            }
 95→
 96→            env.insert(key, value);
 97→        } else {
 98→            return Err(BivvyError::ConfigParseError {
 99→                path: source_path.to_path_buf(),
100→                message: format!("Invalid line {}: {}", line_num + 1, line),
101→            });
102→        }
103→    }
104→
105→    Ok(env)
106→}
107→
108→/// Check if an environment variable name matches secret patterns.
109→///
110→/// Checks against both built-in `SECRET_PATTERNS` and any additional
111→/// patterns provided.
112→pub fn is_secret(name: &str, additional_patterns: &[String]) -> bool {
113→    let all_patterns: Vec<&str> = SECRET_PATTERNS
114→        .iter()
115→        .copied()
116→        .chain(additional_patterns.iter().map(|s| s.as_str()))
117→        .collect();
118→
119→    for pattern in all_patterns {
120→        if matches_pattern(name, pattern) {
121→            return true;
122→        }
123→    }
124→
125→    false
126→}
127→
128→/// Simple glob-style pattern matching (* matches any characters).
129→fn matches_pattern(name: &str, pattern: &str) -> bool {
130→    if pattern.starts_with('*') && pattern.ends_with('*') && pattern.len() >= 2 {
131→        // *MIDDLE* - contains
132→        let middle = &pattern[1..pattern.len() - 1];
133→        name.contains(middle)
134→    } else if let Some(suffix) = pattern.strip_prefix('*') {
135→        // *SUFFIX - ends with
136→        name.ends_with(suffix)
137→    } else if let Some(prefix) = pattern.strip_suffix('*') {
138→        // PREFIX* - starts with
139→        name.starts_with(prefix)
140→    } else {
141→        // Exact match
142→        name == pattern
143→    }
144→}
145→
146→/// Merge environment maps in precedence order.
147→///
148→/// Values in `overlay` take precedence over values in `base`.
149→pub fn merge_env(
150→    base: &HashMap<String, String>,
151→    overlay: &HashMap<String, String>,
152→) -> HashMap<String, String> {
153→    let mut result = base.clone();
154→    result.extend(overlay.iter().map(|(k, v)| (k.clone(), v.clone())));
155→    result
156→}
